{
  "name": "@amykit/plugin-serial-engine",
  "version": "0.6.0",
  "description": "Advances one work item by one move per tick.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/serial-engine"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/plugin-file-queue": "^0.6.0",
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import {
  Action,
  ActionContext,
  AnnouncementKind,
  Budget,
  Event,
  EventKind,
  EventLog,
  Notifier,
  Plan,
  Progress,
  Queue,
  QueueItem,
  StopSwitch,
  Store,
  PortLookup,
  WorkRecord,
  Workflow,
  WorkflowRuntime,
  actionsOf,
  applyPlan,
  cameFrom,
  connects,
  dispatchesTo,
  implementationOf,
  laneMoved,
  movedBy,
  notATryIn,
  portReachedBy,
  runAction,
  undeclaredIn,
} from "@amykit/core";

export interface WorkerConfig {
  /** How long a claimed item may sit before it is treated as abandoned. */
  staleClaimMs: number;
  /** How long finished queue items are kept before being pruned. */
  retentionDays: number;
  /** How many times one item may fail before the machine gives up on it. */
  maxItemAttempts: number;
  /** How long to hold a failed item before looking at it again. */
  retryDelayMs: number;
}

export interface WorkerDeps {
  queue: Queue;
  records: Store;
  /** The order the states happen in, and what the workflow says it emits. */
  workflow: Workflow;
  /**
   * How that workflow's actions actually run.
   *
   * This is the whole reason this engine is not welded to one domain. What
   * used to be here — an observation built out of a tracker, a handler per
   * ticket action, a fold that knew what a gate result is — is on the other
   * side of this interface now, in the package that knows what those words
   * mean.
   */
  runtime: WorkflowRuntime;
  /**
   * The mounted ports, for an action the runtime declared as a port and a
   * method rather than as a handler. Optional, so an engine whose workflow
   * wrote every handler itself still runs.
   */
  port?: PortLookup;
  /** Core's own port, and the only one left here: a failure has to be sayable. */
  notifier: Notifier;
  now: () => Date;
  config: WorkerConfig;
  /** Optional, so an engine with no log still runs. */
  log?: EventLog;
  /** Optional, so an engine with no handbrake still runs. */
  stop?: StopSwitch;
  /** Optional, so an engine with no ceiling on spending still runs. */
  budget?: Budget;
  /**
   * How the lanes of a fork move. `serial`, the default, moves one lane per
   * look, in turn; `concurrent` moves every lane that has a move at once, one
   * move each, and folds them into the one record it claimed.
   */
  lanes?: "serial" | "concurrent";
}

/** The one result the budget produces, named so the check can return it. */
export type Parked = Extract<TickResult, { kind: "parked" }>;

export type TickResult =
  | { kind: "idle" }
  | { kind: "stopped"; reason: string }
  | {
      kind: "worked";
      workId: string;
      from: string;
      to: string;
      plan: Plan["kind"];
      why: string;
      /** Set when the plan asked to be looked at again later. */
      retryAfterMs?: number;
    }
  | { kind: "failed"; workId: string; state: string; error: string }
  /** The move would have spent an agent, and the budget said not yet. */
  | {
      kind: "parked";
      workId: string;
      state: string;
      reason: string;
      retryAfterMs: number;
    };

/**
 * Advances at most one piece of work by at most one move, then chains the
 * next look.
 *
 * Nothing here decides *when* the next step runs. A step that takes a minute
 * and a step that takes an hour both enqueue their successor the moment they
 * finish, so the queue is the schedule.
 *
 * Nothing here decides *what* a step is, either. Every noun in this file is
 * queue, record, attempt, budget or stop; a ticket, a pull request and a
 * reviewer are all on the far side of `runtime`.
 */
export class Worker {
  constructor(private readonly deps: WorkerDeps) {}

  /**
   * Puts every piece of work the runtime can find onto the queue.
   *
   * Work already waiting is not queued twice, but its urgency is refreshed:
   * discovery is the one moment the source is asked, so it is the one moment
   * a priority somebody changed can reach what is already queued.
   */
  async discover(): Promise<string[]> {
    const now = this.deps.now();
    const enqueued: string[] = [];
    const terminal = this.deps.workflow.terminalStates;

    for (const found of await this.deps.runtime.found()) {
      const { workId, priority } = typeof found === "string" ? { workId: found, priority: undefined } : found;
      const existing = this.deps.records.load(workId);
      if (existing && terminal.includes(existing.state)) continue;
      if (this.deps.queue.pending().some((item) => item.workId === workId)) {
        this.deps.queue.reprioritize?.(workId, priority);
        continue;
      }

      // Work the engine has already let go of is not brought back by a look.
      // The record says so, and says it durably: the queue's history is
      // pruned, and inferring from it would bring this work back at attempt
      // zero as soon as retention ran. `amy look <id>` is the named way back.
      if (existing?.gaveUp) continue;

      this.deps.queue.enqueue({ workId, reason: "found by the workflow", priority }, now);
      enqueued.push(workId);
    }

    return enqueued;
  }

  async tick(): Promise<TickResult> {
    const now = this.deps.now();

    // Asked before anything is claimed, so a stop cannot be overtaken by one
    // more piece of work sneaking onto the queue.
    const halted = this.halted();
    if (halted) return halted;

    this.deps.queue.recover(this.deps.config.staleClaimMs, now);

    const item = this.deps.queue.claim(now);
    if (!item) {
      this.record("run.idle");
      return { kind: "idle" };
    }

    this.record("run.claimed", { workId: item.workId, detail: { reason: item.reason } });

    const record =
      this.deps.records.load(item.workId) ?? this.deps.runtime.newRecord(item.workId, now);

    try {
      return await this.advance(item, record, now);
    } catch (error) {
      return await this.recordFailure(item, record, error);
    }
  }

  private async advance(item: QueueItem, record: WorkRecord, now: Date): Promise<TickResult> {
    const observation = await this.deps.runtime.observe(record);
    const side = this.deps.workflow.everyLane?.(record, observation, this.deps.runtime.policy);
    if (side && this.deps.lanes === "concurrent") return this.advanceLanes(item, record, observation, side, now);
    const decision = side ? this.laneInTurn(item, record, side, now) : this.deps.workflow.plan(record, observation, this.deps.runtime.policy);
    if (decision.kind === "parked") {
      this.park(item, decision, now);
      return decision;
    }

    this.record("work.planned", {
      workId: item.workId,
      state: record.state,
      detail: { plan: decision.kind, why: decision.why },
    });

    if (decision.kind === "settled") {
      this.record("work.settled", { workId: item.workId, state: record.state });
      // A terminal state reached after a fall *is* the work carrying on from
      // where it was, so it is worth the same one warning.
      await this.announceRecovery(item, record.state);
      this.deps.queue.complete(item);
      this.maybePrune(now);
      return {
        kind: "worked",
        workId: item.workId,
        from: record.state,
        to: record.state,
        plan: "settled",
        why: decision.why,
      };
    }

    const actions = actionsOf(decision);

    const parked = this.parked(record, actions, now) ?? this.progressParked(item, record, actions, accountOf(record, decision));
    if (parked) {
      this.park(item, parked, now);
      return parked;
    }

    const outcomes = await this.execute(observation, record, decision);
    const progress = this.progressAfter(item, record, decision, actions, outcomes);
    // The core folds state, attempts and history; the runtime folds the domain.
    // An action can park itself, so save its fold before returning. A manual
    // release must not replay stale state or bypass its attempt ceiling.
    const next = this.deps.runtime.apply(
      applyPlan(record, decision, now, outcomes),
      decision,
      outcomes,
      observation,
      now,
      movedBy(record, decision),
    );
    this.deps.records.save(next);
    // Only once the move is saved: an action or a fold that threw left the
    // work where it was, and the line would claim a move that never happened.
    this.undrawn(item, record, decision);
    if (progress.parked) {
      this.park({ ...item, progress: progress.next }, progress.parked, now);
      return progress.parked;
    }

    // The core folds the state, the attempt count and the history; the
    // runtime folds what only it can read. Two calls rather than one because
    // the second cannot be written without knowing the domain, and this
    // engine is the half that does not. The move is handed over as well,
    // because the record the runtime gets has already made it.
    const delayMs = retryAfter(decision, outcomes, this.deps.config.retryDelayMs);
    // The hold starts when the look ends: an agent cut off after minutes must
    // still be held for the whole delay its outcome named.
    this.deps.queue.enqueue(
      {
        workId: item.workId,
        reason: decision.why,
        delayMs,
        progress: progress.next,
        priority: item.priority,
      },
      this.deps.now(),
    );

    this.deps.queue.complete(item);
    this.maybePrune(now);

    this.record(decision.kind === "wait" ? "work.waiting" : "work.advanced", {
      workId: item.workId,
      state: next.state,
      detail: { from: record.state, why: decision.why },
    });

    await this.announceRecovery(item, next.state);

    return {
      kind: "worked",
      workId: item.workId,
      from: record.state,
      to: next.state,
      plan: decision.kind,
      why: decision.why,
      retryAfterMs: delayMs || undefined,
    };
  }

  /**
   * The one lane the serial engine moves, of those that have a move: the
   * first in turn that the budget and the evidence check allow, so a lane that
   * may not run never holds its siblings up. A look that failed is tried again
   * with the turn moved on, so a lane that keeps throwing does not either.
   * Parked only when no lane may move.
   */
  private laneInTurn(item: QueueItem, record: WorkRecord, plans: readonly Plan[], now: Date): Plan | Parked {
    const allowed = plans.filter((plan) => !this.parked(record, actionsOf(plan), now) && !this.progressParked(item, record, actionsOf(plan), accountOf(record, plan)));
    if (allowed.length === 0) return this.parked(record, actionsOf(plans[0]!), now) ?? this.progressParked(item, record, actionsOf(plans[0]!), accountOf(record, plans[0]!))!;
    return allowed[item.attempt % allowed.length]!;
  }

  /**
   * One move for every lane that has one, side by side, folded into the one
   * record this tick claimed.
   *
   * Each lane passes the budget check before its call, as any move does; a
   * lane the budget refuses waits for the next look while the rest go on.
   * The lanes write to records of their own, so folding them in turn is the
   * same record whatever order they finished in.
   */
  private async advanceLanes(item: QueueItem, record: WorkRecord, observation: unknown, plans: readonly Plan[], now: Date): Promise<TickResult> {
    // Each lane is asked what any move is asked before its call: the budget,
    // and whether another agent run would add any evidence.
    const refusal = (plan: Plan): Parked | null => this.parked(record, actionsOf(plan), now) ?? this.progressParked(item, record, actionsOf(plan), accountOf(record, plan));
    const allowed = plans.filter((plan) => !refusal(plan));
    if (allowed.length === 0) {
      const parked = refusal(plans[0]!)!;
      this.park(item, parked, now);
      return parked;
    }
    for (const plan of allowed) {
      this.record("work.planned", { workId: item.workId, state: record.state, detail: { plan: plan.kind, why: plan.why } });
    }
    // Settled one by one: a lane that threw must not cost its siblings the
    // moves they made, and paid for. Theirs are kept; the failure is the
    // item's, as a serial look's would be.
    const settled = await Promise.allSettled(allowed.map((plan) => this.execute(observation, record, plan)));
    const moved = allowed.flatMap((plan, index) => {
      const result = settled[index]!;
      return result.status === "fulfilled" ? [{ plan, outcomes: result.value }] : [];
    });
    let next = record;
    for (const { plan, outcomes } of moved) {
      next = this.deps.runtime.apply(applyPlan(next, plan, now, outcomes), plan, outcomes, observation, now, null);
    }
    this.deps.records.save(next);
    const progress = this.lanesProgress(item, record, moved);
    const failed = settled.find((result): result is PromiseRejectedResult => result.status === "rejected");
    // The look failed, and the evidence its other lanes reported still counts:
    // a retry must not buy them a run past the ceiling.
    if (failed) return this.recordFailure({ ...item, progress: progress.next }, next, failed.reason);
    if (progress.parked) {
      this.park({ ...item, progress: progress.next }, progress.parked, now);
      return progress.parked;
    }

    const delayMs = Math.min(...moved.map(({ plan, outcomes }) => retryAfter(plan, outcomes, this.deps.config.retryDelayMs)));
    this.deps.queue.enqueue({ workId: item.workId, reason: allowed.map((plan) => plan.why).join("; "), delayMs, progress: progress.next, priority: item.priority }, this.deps.now());
    this.deps.queue.complete(item);
    this.maybePrune(now);
    this.record("work.advanced", { workId: item.workId, state: next.state, detail: { from: record.state, why: `${allowed.length} lanes moved` } });
    await this.announceRecovery(item, next.state);

    return {
      kind: "worked",
      workId: item.workId,
      from: record.state,
      to: next.state,
      plan: "act",
      why: allowed.map((plan) => plan.why).join("; "),
      retryAfterMs: delayMs || undefined,
    };
  }

  /** What every lane's move says about evidence, folded in turn as the serial engine folds one. */
  private lanesProgress(
    item: QueueItem,
    record: WorkRecord,
    moved: readonly { plan: Plan; outcomes: Record<string, unknown> }[],
  ): { next: QueueItem["progress"]; parked?: Parked } {
    let next = item.progress;
    let parked: Parked | undefined;
    for (const { plan, outcomes } of moved) {
      const after = this.progressAfter({ ...item, progress: next }, record, plan, actionsOf(plan), outcomes);
      next = after.next;
      parked ??= after.parked;
    }
    return { next, ...(parked ? { parked } : {}) };
  }

  /**
   * A budget refusal, when this move would spend an agent and the ceiling is
   * already reached.
   *
   * The record is deliberately not saved: the work keeps its state and its
   * per-state attempt count, and only its next look moves. Parked, not lost.
   * The queue item's own attempt count is carried by the caller, which is a
   * different counter and has to be said, not assumed.
   */
  private parked(record: WorkRecord, actions: readonly Action[], now: Date): Parked | null {
    if (!this.deps.budget) return null;

    const spending = this.agentActions(actions).map((action) => action.type);
    if (spending.length === 0) return null;

    const decision = this.deps.budget.mayStart(now);
    if (decision.ok) return null;

    this.record("budget.parked", {
      workId: record.id,
      state: record.state,
      detail: {
        window: decision.window,
        measure: decision.measure,
        used: decision.used,
        limit: decision.limit,
        stopAt: decision.stopAt,
        retryAfterMs: decision.retryAfterMs,
        pending: spending,
      },
    });

    return {
      kind: "parked",
      workId: record.id,
      state: record.state,
      reason: decision.reason,
      retryAfterMs: decision.retryAfterMs,
    };
  }

  private progressParked(
    item: QueueItem,
    record: WorkRecord,
    actions: readonly Action[],
    state = record.state,
  ): Parked | null {
    const policy = this.deps.runtime.progress;
    const spending = this.agentActions(actions);
    if (!policy || spending.length === 0) return null;
    const current = item.progress ?? {};
    const prefix = `${state}:`;
    const blocked = Object.entries(current).find(([key, value]) =>
      key.startsWith(prefix) && value.count >= policy.maxUnchanged,
    );
    if (!blocked) return null;

    const [stored, value] = blocked;
    const key = stored.slice(prefix.length);
    const pending = spending.map((action) => action.type);
    const reason = `another agent run in ${state} would add no evidence for ${key}: ${value.detail}`;
    this.record("progress.parked", {
      workId: record.id,
      state,
      detail: { key, detail: value.detail, maxUnchanged: policy.maxUnchanged, pending },
    });
    return { kind: "parked", workId: record.id, state, reason, retryAfterMs: this.deps.config.retryDelayMs };
  }

  private progressAfter(
    item: QueueItem,
    record: WorkRecord,
    decision: Plan,
    actions: readonly Action[],
    outcomes: Record<string, unknown>,
  ): { next: Record<string, { count: number; detail: string }> | undefined; parked?: Parked } {
    const policy = this.deps.runtime.progress;
    if (!policy || this.agentActions(actions).length === 0) return { next: item.progress };
    const signals = progressSignals(outcomes);
    if (signals.length === 0) return { next: item.progress };

    const next = { ...(item.progress ?? {}) };
    const state = movedBy(record, decision)?.to ?? accountOf(record, decision);
    for (const signal of signals) {
      if (signal.kind === "advanced") {
        // The signal came from the state this look started in. Clearing only
        // the destination would resurrect an old ceiling if work later
        // returns here; clear the destination too in case it already held one.
        delete next[progressKey(accountOf(record, decision), signal.key)];
        delete next[progressKey(state, signal.key)];
        continue;
      }
      if (signal.kind === "unchanged") {
        const key = progressKey(state, signal.key);
        const previous = next[key]?.count ?? 0;
        next[key] = { count: previous + 1, detail: signal.detail };
        continue;
      }
      next[progressKey(state, "handoff")] = { count: policy.maxUnchanged, detail: signal.detail };
      return { next, parked: this.progressParked({ ...item, progress: next }, record, actions, state)! };
    }
    return { next: Object.keys(next).length > 0 ? next : undefined };
  }

  /** Core actions have a stable dispatch table; custom actions name their port in the runtime. */
  private agentActions(actions: readonly Action[]): Action[] {
    return actions.filter((action) => {
      if (dispatchesTo(action.type, "agent")) return true;
      return portReachedBy(implementationOf(this.deps.runtime, action.type)) === "agent";
    });
  }

  private park(item: QueueItem, parked: Parked, now: Date): void {
    this.deps.queue.enqueue({
      workId: item.workId,
      reason: parked.reason,
      delayMs: parked.retryAfterMs,
      attempt: item.attempt,
      progress: item.progress,
      priority: item.priority,
    }, now);
    this.deps.queue.complete(item);
    this.maybePrune(now);
  }

  private async recordFailure(
    item: QueueItem,
    record: WorkRecord,
    error: unknown,
  ): Promise<TickResult> {
    const message = error instanceof Error ? error.message : String(error);
    const attempt = item.attempt + 1;
    const now = this.deps.now();

    this.record("work.failed", {
      workId: item.workId,
      state: record.state,
      detail: { attempt, error: message },
    });

    if (attempt >= this.deps.config.maxItemAttempts) {
      // The ceiling, said once, on the record as it is now: the failed move
      // may already have been saved, and the pre-tick snapshot would undo it.
      // Written before the item is completed, so a discovery running while
      // the notice is sent cannot queue the work again at attempt zero.
      const latest = this.deps.records.load(item.workId) ?? record;
      this.deps.records.save({ ...latest, gaveUp: { at: now.toISOString(), reason: message } });
    }

    this.deps.queue.complete(item);

    // Routed through `announce`, not straight at the port. The item is
    // already completed by this point, so a single broken channel used to
    // throw past `tick()` and the work left the queue with no record of why.
    const notice = this.failureNotice(item, record, attempt, message);
    if (notice) await this.announce(notice.text, item.workId, record.state, notice.kind);

    if (attempt < this.deps.config.maxItemAttempts) {
      this.deps.queue.enqueue(
        {
          workId: item.workId,
          reason: `retrying after an error: ${message}`,
          delayMs: this.deps.config.retryDelayMs,
          attempt,
          // A failure retries the same look, not a fresh one. Retain the
          // no-evidence streak so a transient dependency failure cannot
          // spend an extra agent run past the configured ceiling.
          progress: item.progress,
          priority: item.priority,
        },
        now,
      );
    }

    return { kind: "failed", workId: item.workId, state: record.state, error: message };
  }

  /**
   * What to say about a failure: one warning on the way down, silence in the
   * middle, one at the ceiling. `null` is the silence.
   *
   * The signal is `QueueItem.attempt`, which is durable, already crosses
   * processes, already counts consecutive failures of this work, and is
   * already zeroed by the event that means recovery. `amy tick` is a fresh
   * process every time, so a counter on the worker could not do this.
   *
   * The ceiling wins over the fall, so `maxItemAttempts: 1` produces one
   * warning rather than two. The guard is `item.attempt === 0` and not
   * `attempt === 1` because it reads as "this item had never failed before",
   * which is the condition that is actually true.
   */
  private failureNotice(
    item: QueueItem,
    record: WorkRecord,
    attempt: number,
    message: string,
  ): { text: string; kind: AnnouncementKind } | null {
    if (attempt >= this.deps.config.maxItemAttempts) {
      return {
        text: `${item.workId} failed ${attempt} times in ${record.state}, I have given up, and it is off the queue: ${message}`,
        kind: "gave-up",
      };
    }

    if (item.attempt !== 0) return null;

    this.record("work.degraded", {
      workId: item.workId,
      state: record.state,
      detail: { attempt, error: message },
    });

    return {
      text: `${item.workId} is failing in ${record.state} and I am retrying: ${message}`,
      kind: "failing",
    };
  }

  /**
   * One warning when the work moves again, and nothing at all if it never
   * stopped.
   *
   * There is deliberately no recovery after the ceiling. Past it the item
   * leaves the queue and the next one comes from `amy discover` at attempt
   * zero, so nothing carries the history. The ceiling warning already said
   * "I have stopped, come and look", and announcing a recovery there would
   * give the machine credit for a person's repair.
   */
  private async announceRecovery(item: QueueItem, state: string): Promise<void> {
    if (item.attempt === 0) return;

    this.record("work.recovered", {
      workId: item.workId,
      state,
      detail: { afterAttempts: item.attempt },
    });

    await this.announce(
      `${item.workId} is moving again in ${state} after ${item.attempt} failed attempt(s).`,
      item.workId,
      state,
      "recovered",
    );
  }

  private async execute(
    observation: unknown,
    record: WorkRecord,
    plan: Plan,
  ): Promise<Record<string, unknown>> {
    const outcomes: Record<string, unknown> = {};
    const ctx: ActionContext = { record, observation, outcomes };
    const runtime = this.deps.runtime;
    const port = this.deps.port ?? ((): undefined => undefined);

    // Asked of the whole plan before its first action runs, so a plan that
    // carries something the workflow never declared is refused with nothing
    // half-done behind it rather than after the actions ahead of it.
    const undeclared = undeclaredIn(runtime, plan);
    if (undeclared.length > 0) {
      throw new Error(
        `the plan in ${record.state} carries ${undeclared.map((name) => `"${name}"`).join(", ")}, ` +
          `which the workflow never declared in its actions`,
      );
    }

    for (const action of actionsOf(plan)) {
      // Between actions as well as between ticks, because a plan can carry
      // several and a stop should not have to wait for the last one.
      if (this.deps.stop?.isRequested()) {
        this.record("stop.enforced", {
          workId: record.id,
          state: record.state,
          detail: { pending: action.type, reason: this.deps.stop.reason() },
        });
        break;
      }

      this.record("action.started", { workId: record.id, detail: { action: action.type } });
      try {
        await runAction(implementationOf(runtime, action.type), action, ctx, port);
        this.record("action.finished", { workId: record.id, detail: { action: action.type } });
      } catch (error) {
        this.record("action.failed", {
          workId: record.id,
          detail: {
            action: action.type,
            error: error instanceof Error ? error.message : String(error),
          },
        });
        throw error;
      }
    }

    return outcomes;
  }

  /**
   * Says something to the operator, and never lets that cost a piece of work.
   *
   * A port call may only be swallowed when its failure does not make the
   * saved record a lie, and this is the one that qualifies: nothing
   * downstream reads a notification. Every other port is reached through the
   * runtime and is deliberately not wrapped — see
   * `docs/design/the-engine-fails-out-loud.md`.
   *
   * It lives here rather than only in the fan-out because `notifier` is a
   * port and an install may mount something else behind it. The promise is
   * the engine's, not the mounted plugin's.
   */
  private async announce(
    text: string,
    workId: string,
    state: string,
    kind?: AnnouncementKind,
  ): Promise<void> {
    try {
      await this.deps.notifier.announce({ text, workId, state, ...(kind ? { kind } : {}) });
    } catch (error) {
      this.record("notify.failed", {
        workId,
        state,
        detail: { error: error instanceof Error ? error.message : String(error), text },
      });
    }
  }

  /**
   * Appends to the log if there is one, and shrugs if there is not.
   *
   * A full disk or a bad permission under `.amy/log` must not cost a piece of
   * work a move, and must not be silent either, or the machine looks healthy
   * while keeping no record of anything.
   *
   * Once per worker: a broken log throws on every one of the eight or so
   * calls in a tick, and a flood in stderr is its own outage. It does not
   * announce — `announce` writes under `.amy/` too, so on a machine whose log
   * just broke it is the wrong thing to trust.
   */
  private record(kind: EventKind, rest: Omit<Event, "at" | "kind"> = {}): void {
    try {
      this.deps.log?.append({ at: this.deps.now().toISOString(), kind, ...rest });
    } catch (error) {
      if (this.saidTheLogIsBroken) return;
      this.saidTheLogIsBroken = true;
      const why = error instanceof Error ? error.message : String(error);
      console.error(`amy cannot write its event log, and is carrying on without it: ${why}`);
    }
  }

  /**
   * Writes down a move the workflow's diagram does not connect, once it is saved.
   *
   * The move is still made: refusing it would leave somebody's work stuck
   * because of a drawing mistake, and the log is where the drawing gets fixed.
   */
  private undrawn(item: QueueItem, record: WorkRecord, decision: Plan): void {
    const diagram = this.deps.workflow.diagram;
    if (!diagram || decision.kind !== "advance") return;
    if (connects(diagram, record.state, decision.to, cameFrom(record.history, record.state))) return;
    this.record("workflow.undrawn_transition", {
      workId: item.workId,
      state: record.state,
      detail: { from: record.state, to: decision.to },
    });
  }

  /** So a log that throws on every call says so once, not eight times. */
  private saidTheLogIsBroken = false;

  /**
   * A stop request, if one is in force.
   *
   * Returning the result rather than throwing, because a stop is an outcome
   * the operator asked for, not a failure to be retried.
   */
  private halted(): TickResult | null {
    if (!this.deps.stop?.isRequested()) return null;

    const reason = this.deps.stop.reason() ?? "no reason given";
    this.record("stop.enforced", { detail: { reason } });
    return { kind: "stopped", reason };
  }

  /** Finished items are swept on the way past rather than accumulating forever. */
  private maybePrune(now: Date): void {
    this.deps.queue.prune(this.deps.config.retentionDays, now);
  }
}

/**
 * Where a move's evidence is counted: its state, or, for a lane's move, the
 * lane within it — so one lane's runs that added nothing never park a sibling
 * that has not run, and moving lanes in turn or side by side ends the same.
 */
function accountOf(record: WorkRecord, plan: Plan): string {
  const lane = laneMoved(plan);
  return lane === undefined ? record.state : `${record.state}/${lane}`;
}

function progressKey(state: string, key: string): string {
  return `${state}:${key}`;
}

/** A completed action can say it never reached the part that spends a try. */
function retryAfter(plan: Plan, outcomes: Record<string, unknown>, fallback: number): number {
  const outcome = notATryIn(outcomes);
  if (plan.kind === "act" && outcome) return outcome.retryAfterMs ?? fallback;
  return plan.kind === "wait" ? plan.retryAfterMs : 0;
}

function isProgress(value: unknown): value is Progress {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Record<string, unknown>;
  if (candidate.kind === "advanced") return typeof candidate.key === "string";
  if (candidate.kind === "unchanged") {
    return typeof candidate.key === "string" && typeof candidate.detail === "string";
  }
  return candidate.kind === "handoff" && typeof candidate.detail === "string";
}

/** Supports generic runtimes while reading the progress field of the ticket contract. */
function progressSignals(outcomes: Record<string, unknown>): Progress[] {
  return Object.values(outcomes).flatMap((outcome) => {
    if (isProgress(outcome)) return [outcome];
    if (!outcome || typeof outcome !== "object") return [];
    const progress = (outcome as Record<string, unknown>).progress;
    return isProgress(progress) ? [progress] : [];
  });
}

import { ConfigSchema } from "@amykit/core";

/**
 * What this plugin needs told to it, and nothing more.
 *
 * `repos`, `qaStatusName` and `policy` used to be here. They are the
 * workflow's vocabulary, not an engine's, and they moved to the workflow's
 * own slice when the engine stopped knowing what a ticket is.
 */
export const configSchema = {
  staleClaimMs: {
    type: "number",
    description: "how long a claimed item may sit before it counts as abandoned",
    default: 30 * 60 * 1000,
  },
  retentionDays: {
    type: "number",
    description: "how long a finished queue item is kept before it is pruned",
    default: 7,
  },
  maxItemAttempts: {
    type: "number",
    description: "how many times one item may fail before the operator is told and it is dropped",
    default: 5,
  },
  retryDelayMs: {
    type: "number",
    description: "how long a failed item is held before it is looked at again",
    default: 5 * 60 * 1000,
  },
} satisfies ConfigSchema;

export { Worker } from "./Worker.js";
export type { TickResult, WorkerConfig, WorkerDeps } from "./Worker.js";
export { configSchema } from "./config.js";
export { engineFor, plugin } from "./plugin.js";

import {
  Budget,
  Engine,
  Notifier,
  definePlugin,
  PluginContext,
  Queue,
  Store,
  WORKFLOW_RUNTIME,
  Workflow,
  WorkflowRuntime,
  deferred,
  ConfigOf,
} from "@amykit/core";
import { Worker } from "./Worker.js";
import { configSchema } from "./config.js";

type TypedContext = PluginContext<ConfigOf<typeof configSchema>>;

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-serial-engine",
  configSchema,
  register(registry, ctx) {
    // Deferred: the workflow and the ports it needs are registered by plugins
    // that may be listed after this one. The host builds it once every plugin
    // has registered, so an engine with no workflow, or a workflow with no
    // queue, is refused at boot rather than on the first tick.
    registry.engine(deferred((): Engine => engineFor(ctx, "serial")));
  },
});

/**
 * The engine over the mounted workflow, its lanes moved one per look or side
 * by side. Exported for the concurrent engine, which is this one with its
 * lanes moved at once, so the two cannot drift apart on anything else.
 */
export function engineFor(ctx: PluginContext<ConfigOf<typeof configSchema>>, lanes: "serial" | "concurrent"): Engine {
  const worker = build(ctx, lanes);
  return { discover: () => worker.discover(), tick: () => worker.tick() };
}

function build(ctx: TypedContext, lanes: "serial" | "concurrent"): Worker {
  const workflow = ctx.workflow() as Workflow | undefined;
  if (!workflow) {
    throw new Error("the serial engine needs a workflow, and no plugin registered one");
  }

  // The pair first: a workflow with no runtime is an engine that cannot
  // mean anything, and saying so beats reporting a missing queue to somebody
  // whose real problem is a half-mounted workflow.
  const runtime = runtimeFor(ctx, workflow);
  if (!ctx.workflowPort) {
    throw new Error("the serial engine needs a core with workflow-scoped ports; upgrade @amykit/core");
  }

  return new Worker({
    queue: required<Queue>(ctx, "queue"),
    records: required<Store>(ctx, "store"),
    workflow,
    runtime,
    notifier: required<Notifier>(ctx, "notifier"),
    // For an action the workflow wired as a port and a method: the engine
    // calls it, so the engine is what has to reach the port.
    port: (kind) => ctx.workflowPort!(kind),
    now: ctx.now,
    log: ctx.log,
    // Optional: an install that set no ceiling mounts no budget, and this
    // engine then never asks one.
    budget: ctx.port("budget") as Budget | undefined,
    lanes,
    config: {
      staleClaimMs: ctx.config.staleClaimMs,
      retentionDays: ctx.config.retentionDays,
      maxItemAttempts: ctx.config.maxItemAttempts,
      retryDelayMs: ctx.config.retryDelayMs,
    },
  });
}

/**
 * The runtime the mounted workflow contributed.
 *
 * Looked up by the workflow's own name, so an install that mounts two
 * workflows and one runtime is refused here rather than driving the wrong
 * half of itself. Naming what there was to choose from, because a
 * mismatched pair is a config mistake and the fix is a name.
 */
function runtimeFor(ctx: TypedContext, workflow: Workflow): WorkflowRuntime {
  const contributed = ctx.contributions(WORKFLOW_RUNTIME);
  const runtime = contributed.get(workflow.name);

  if (!runtime) {
    const offered = [...contributed.keys()].join(", ") || "nothing";
    throw new Error(
      `the workflow \`${workflow.name}\` contributed no runtime to \`${WORKFLOW_RUNTIME}\`, ` +
        `so nothing here knows how to run its actions. Contributed: ${offered}`,
    );
  }

  return runtime as WorkflowRuntime;
}

/**
 * Something this engine cannot work without.
 *
 * The loader already refuses a mount where an action has no port, so reaching
 * here means something registered an engine without the rest. Saying which
 * one beats a property access on undefined.
 */
function required<T>(ctx: TypedContext, kind: string): T {
  const port = ctx.port(kind);
  if (!port) {
    throw new Error(`the serial engine needs the \`${kind}\` port, and nothing mounted it`);
  }
  return port as T;
}
